  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (446::BIGINT, 'Es muy desordenada, usa un formato de Tecdigital que no entiende ni ella, los trabajos son larguísimos por porcentajes bajos en la nota, cambia el cronograma de clases a conveniencia, cancela las clases de la nada, las presentaciones son demasiado confusas y caducan, se pasa, pero es un bostezo'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2026-11-02T00:00:00+00:00'::TIMESTAMPTZ, 'b51ed43cd64711bf5e79377bf5ec22e3caa8ca34f2262a1a4125b9d49f3e33a2'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (446::BIGINT, 'Si usted matricula con ella, tenga por seguro que de 16 semanas de clase, van a tener 5 veces que ir a la clase contando los exámenes, todo es en grupo menos el último examen, las clases virtuales asincrónicas son del 2020 porque esta profesora es ridículamente vaga, las clases que da son malas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, '2885322624530492f8bfc4c502dfd72acf32571e74cf86fb1ce6ac8437abe996'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (446::BIGINT, 'Buena gente, ha cambiado mucho la metodología según leo. Vale la pena matricular con ella'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-23T00:00:00+00:00'::TIMESTAMPTZ, '6d4daeb29ce041d9988e66927374a7e3435cfd0fe0e83452feb700e410b9218f'::TEXT, ARRAY[1742]::BIGINT[]),
    (446::BIGINT, 'Todo el curso es en grupo menos el último examen entonces es importante hacerse con personas que entiendan bien. Dura demasiado en dar las calificaciones y en general es bastante vaga para calificar y resolver reclamos o dudad'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-08-04T00:00:00+00:00'::TIMESTAMPTZ, '299ab3d0b28d40711b641c7501cc88f10064df2722e2a6ca812caca9ecbfdecb'::TEXT, ARRAY[963]::BIGINT[]),
    (446::BIGINT, 'Las clases son bastante confusas, se desvía demasiado del tema cuando está explicando algo. Siempre se contradice y es casi imposible que acepte cuando se equivoca. Los métodos de evaluación no son claros y es muy estricta para lo poco que ofrece como profesora. Cero empatía.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '4cf6ce47a77555286137e425d08a2ad6568265d95892ef78ebee0e2dd322cf63'::TEXT, ARRAY[963]::BIGINT[]),
    (446::BIGINT, 'Es la peor profesora que he tenido. La mae da puntos extra y con eso se trata de justificar. Cambió los procentajes de los exámenes solo porque quería sin consultar a la clase. No acepta nada tarde por más bueno que sea el trabajo. Es terrible y la vergüenza de la escuela de produ.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, '6e3f3c4a541941194dbd305eba9db5dbd30c66c1fe5e6e4a6945567f2bf75bd5'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Sinceramente esta profe no es nada buena, no es nada empática, se pasa contradiciendo, cuando se trata de un trabajo no deja en claro lo que va a evaluar y si usted le reclama algo lo agarra entre ojos, si no le cayo bien su grupo van a pagar en los examenes, no la recomiendo nada'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '37dadfad42f0fc26415f4973a930e78cb839ad5a47723aa1f331d9b887064b2f'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'La profe se pasa contradiciendo, dice que sigue el reglamento pero es solo cuando le conviene, pone videos de clases que grabó en pandemia y no ayuda en nada.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-20T00:00:00+00:00'::TIMESTAMPTZ, '5263031b60be539cf999c469bcd68deec6609147720fcc8af0e6228f8d5d297e'::TEXT, ARRAY[963]::BIGINT[]),
    (446::BIGINT, 'No la recomiendo para nada, ella es demasiado vaga, si el curso es presencial, ella lo hace prácticamente todo asíncronico, califica durísimo y es bastante díficil localizarla La profe quita puntos por un formato que no especifica en evaluaciones.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2025-02-06T00:00:00+00:00'::TIMESTAMPTZ, '6b0cc5cee94de654dd0d1bbd955ef03e4a89bfc463921813909ed9c14eda01dd'::TEXT, ARRAY[963]::BIGINT[]),
    (446::BIGINT, 'La Profe es muuuuy vaga, los exámenes en grupo son una mrd si no tenés un buen grupo, asegúrese de matricular con gente que conozca para que no le toque al azar... Matricule con ella si es su única opción. (Lo llevé en verano)'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'bd700f2cb622cdb21c2ca983b934cafe124cbbfa644e9ac5b35f28a28cf33c20'::TEXT, ARRAY[963]::BIGINT[]),
    (446::BIGINT, 'Es buena profe, pero hay que estudiar bastante. La mayor parte del curso es en grupo. Responde consulta solo una vez por semana, y es importante escribirle para que aclarar dudas y mostrar el interés. Si puede matricule en grupo de 3.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '13d93708885cf95f0343ced5fb4a103ac0f2439a4d034af016cb5ec3533d1fa4'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Todas la evaluaciones son en grupo, algunas algo difíciles y largas. Da puntos extra, a veces deja clases grabadas pero solo están disponibles pocos días y luego las borra'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, '1018070a332751a8ff1fe5d12e3666c2d068eae8aff9001677a889fcf6dab9fe'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'La profe en presencial es muy buena, pero las virtuales o asincrónicas fue lo peor, y hubo muchas clases asincrónicas. Las evaluaciones son acorde a lo visto en clase. Comunicarse con ella es complicado. En general es buena opción y cumple, pero no es la mejor.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'c149feb1d0d59839f1c0c8355f57575cc9fdeb116d40027aa1a0d2f83773c6a0'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'En realidad es una gran profe, es demasiado simpática y trata de hacer la clase bonita'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-24T00:00:00+00:00'::TIMESTAMPTZ, '8b112fb5136553929a74257536df07bc2deb3ec08addf3ff0df85f3c63746cc5'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'La profe no es mala, solo que deja tareas demasiado difíciles y cuenta mucho que atienda consultas. Además que deja todo con poco tiempo. EL curso si quita su tiempo la verdad. No hay que confiarse y es pasable fácilmente'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-05-23T00:00:00+00:00'::TIMESTAMPTZ, 'ef044efa9b66ab9307372db5ee52d024551ec528035f78c042a63fd38ef52a26'::TEXT, ARRAY[963]::BIGINT[]),
    (446::BIGINT, 'Es una profe buena para llevar proba I, da puntos extras y deja práctica para el examen, lo volvería a llevar (lo llevé en verano)'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, '4c23b2d4f9299f9533900b765bb8face27cd8aa4cc095ae43fd492b29784485b'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'La materia definitivamente se las trae pero si quiere pasar matricule con ella. Se ocupa ser mucho autididacta. Casi nunca responde.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Pocos exámenes']::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'b5f31ac1f000b4ef7b1567ebfbf13dad18ac2b23746b4c8b78e05994344eeeac'::TEXT, ARRAY[1446]::BIGINT[]),
    (446::BIGINT, 'Es la mejor profesora del mundo,los que la critican son unos payasos inutiles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2023-09-23T00:00:00+00:00'::TIMESTAMPTZ, 'caf085ce96ca4df4001c0fde0368dd75da640d4b553839e2bf493569c2329634'::TEXT, ARRAY[1034]::BIGINT[]),
    (446::BIGINT, 'No es la mejor profesora pero tampoco la peor a como la pintan. Los exámenes, quices y tareas son larguillos pero la mayoría los hizo grupales. No la recomiendo, pero no le tenga miedo si no le queda otra opción.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos']::TEXT[], '2022-11-14T00:00:00+00:00'::TIMESTAMPTZ, '2b951d7d4383befac2a66f987333cabc50aaae6c26d7ddda1b51ac8a05cafb66'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'La profe no explica mal, las tareas son largas, pero ayudan a prepararse para el examen. Sin embargo, si tiene otra opción, matricule con otro profesor o profesora, porque cuesta mucho que acepte reclamos, y los exámenes son super largos, y si no se hacen en grupo es imposible.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '6f5dd4cdd1cc35a74b78b5f47d0adab301abdc5c6a5eed4de5258f7af967c556'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Vengo saliendo del tercer examen, voy a desahogarme que hp profe más asquerosa, un hp examen larguísimo y el tiempo no da para completarlo todo, aparte de eso mi compu se pega un montón y perdí un bergo de tiempo y tuve que entregarlo a medias y lo mismo pasa con los quices. QUE ASQUEROSIDAD DE PROF'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-01T00:00:00+00:00'::TIMESTAMPTZ, '1e79eee6ff4caf0afc1e2131cc6e3665aeb24ff299e24c17a91403980444cba5'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Esta profesora da la mayoría de los recursos necesarios para pasar el curso, sin embargo el problema son exámenes. Tomando nota y estudiando se pasa. En los exámenes se sigue un formato específico: fórmulas, explicación y minitab. Hace muchas trampas pero si se puede salvar el curso. No es la mejor.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '4c111ec3c83d7383c4d090e12c02a80097b6d33cca0446f2b930563e2db7630e'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (446::BIGINT, 'Si la única opción para matricular es ella, mejor lleva el curso después. A mí me dijeron eso y no hice caso y me arrepiento. Es la peor profesora que existe. Es como llevar un curso de 8 créditos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, '0a17c7250ad8257073ec221eaae3794e7da4559e6839a19496e5bf46d4340cc3'::TEXT, ARRAY[1728, 1742, 1743]::BIGINT[]),
    (446::BIGINT, 'La peor profesora del tec. Nunca da más tiempo para los exámenes o tareas, solo atiende en consulta, nunca da las clases de manera sincrónica, deja trabajos sincrónicos que se extienden más allá de la hora que termina la clase, las tareas y exámenes son excesivamente largos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'a3bbcff3cee9543f34d8659a22f2ca0841d49b00a32127d8e1b278f19f89b007'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Si usted no lee mentes no pasa el curso, a la mae le gustan las cosas de una forma y si no se hacen así se lo pone malo. Las tareas son eternas, para los exámenes el tiempo es demasiado corto en comparación con los ejercicios. Si matricula con ella no meta más de12 créditosporque es misión imposible'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2021-10-27T00:00:00+00:00'::TIMESTAMPTZ, '272ffbbd6b01d1331c2a6383e77b8278cddadd27f02c1f71209b27ee87a0cef7'::TEXT, ARRAY[963, 1728, 1743, 1742]::BIGINT[]),
    (446::BIGINT, 'No es normal lo largo que son sus tareas, todo con la excusa de que estamos en el tec. Las retroalimentaciones de estas son inexistentes, los “solucionarios” que deja no sirven de nada, solo tienen las respuestas y nada de procedimiento (a pesar de que ella lo exige siempre)'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-09-21T00:00:00+00:00'::TIMESTAMPTZ, 'e7710c19c8b416041313edbaa2c98471bd983cb31159351f4a8242223bc3b2cf'::TEXT, ARRAY[963, 1728, 1743, 1742]::BIGINT[]),
    (446::BIGINT, 'Es la peor profe que he tenido en mi carrera universitaria. No tiene empatía y es muy arrogante, pues nunca acepta ningún tipo de reclamo aunque ella se haya equivocado. Los aspectos de evaluación nunca quedan claros.Al final del semestre edita todas las evaluaciones.Trate de no matricular con ella'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ba29f52489abbe6d434024531fd68737bd49b0292be53f86dbd58ae377bdb95b'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (446::BIGINT, 'Me esta jodiendo? Ella ni deberia dar clases en su vida'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-23T00:00:00+00:00'::TIMESTAMPTZ, '2ab63919149a054fb6fd1d712c553c41c9bb638229b7b2fd9d33c78e09e2938b'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'No lo haga compa'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-12-19T00:00:00+00:00'::TIMESTAMPTZ, '7bc607e075c3f2eeb7c2b9e9594659cabd0aa220e159c7f56d790f35c5cfab47'::TEXT, ARRAY[1742]::BIGINT[]),
    (446::BIGINT, 'Es de lo peor que puede tener el TEC. La materia es muy interesante, pero es curso se complica más de lo que debería porque la profe siempre se equivoca en los exámenes y no hay forma que acepte sus errores. La distribución de las evaluaciones no tiene relación con el tiempo que hay que dedicarle.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-13T00:00:00+00:00'::TIMESTAMPTZ, '9edc210207ec51ea3750d7ede60811bd8646c5528efb08c4a6b3a1b0eeed03d8'::TEXT, ARRAY[1742]::BIGINT[]),
    (446::BIGINT, 'La peor profe del tec. No hay ningun tipo de relación entre la carga de los trabajos y su porcentaje. Exámenes demasiado largos y poco claros. No se organiza y deja todo para ultima hora. Es mejor no llevar el curso a llevarlo con Liss. esto nada más para empezar. Debería retirarse. Cero empatía'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-12-12T00:00:00+00:00'::TIMESTAMPTZ, '425f08a437a821e55828a0dbb99ec050373bafc3f33e2fe20f980ffb07cf6da4'::TEXT, ARRAY[1742]::BIGINT[]),
    (446::BIGINT, 'asigno una tarea de 20 ejercicios de un libro, 2 ejercicios extra largos y 3 ejercicios en grupo de los cuales ademas habia que hacer un video para cada uno. Y todo eso como por un 2%. Los examenes y trabajos en clase simplemente no dan tiempo de hacerlos completos. No matricule con ella'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-12-06T00:00:00+00:00'::TIMESTAMPTZ, '71d6dfc04832d0ae77b8bef2fb155ae9696e79cb81b7cb782a0e31de3df80c35'::TEXT, ARRAY[963, 1728, 1743, 1742]::BIGINT[]),
    (446::BIGINT, 'Es un excelente profesional, siento que la califican mal porque hay muchos estudiantes mediocres, ya que ella se encarga de dejar tareas y quices todas las semanas lo que hace que uno vaya al día con la materia y se le haga imposible quedarse.El curso en que mas aprendí.No resp correos,notas tarde.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '13c01ba010432756fac5b488e0ebd2d7c0e9002cfb874ba5db95071fede8d59d'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Por favor no matricule con ella, es horrible. Se contradice, es terca, no responde. Solo subio 2 videos de clases. Siento que violentó mis derechos como estudiante, porque no da notas, demasida carga, examenes mal hechos, poco tiempo, Grosera, muteó a un compañero en media clase. La peor experienci'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '2f00aaff5ee68c166b741e085fd7ff41e7a0112cf96544837a447824b90002f8'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (446::BIGINT, 'Peor profe que he tenido aunque me haya ido bien. Demasiado terca, no acepta cuando se equivoca. Nunca atiende consultas, no responde correos ni aparece en las horas de consulta. Explica regular, se contradice y los examenes tienen muchos errores. Es fácil, pero va a odiarla y se pelea con ella.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '76bdfa1bcaf721a62173051d7aca043f9caa25ab3c60cb1c8e78769570d58f60'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (446::BIGINT, 'No matriculen con ella, es una abusadora, hace lo que quiere con la evaluacion, los examenes mal hechos y llenos de errores, evaluaciones con muy poco tiempo, es absurdo, toda la clase la detestaba al final de semestre, no cumple con su deber como profesora.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '8117087d6f74b4ded546097aeec98fee908ef6048143746f2aa5b07f0ede0845'::TEXT, ARRAY[963, 1728, 1743, 1742]::BIGINT[]),
    (446::BIGINT, 'Es una profesional muy buena, pero la modalidad virtual se la come en el sentido que no acepta reclamos de los estudiantes, se torna ofendida si se le dice algo y las evaluaciones generalmente son muy largas si es virtual y solo le queda ella mejor adelante otra materia.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, '684b9f12b30106a518408d19104027777772f8231f267735ba59366240a0e14a'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Me gustaron las clases con esta profe, se aprende mucho, es solo de poner atención y ponerle!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Da crédito extra']::TEXT[], '2020-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'b436bc60b6cf6f85e6cf5b2f6661c2c5ac259df072ccae52cf1268d322c21f86'::TEXT, ARRAY[1743, 1742]::BIGINT[]),
    (446::BIGINT, 'Explica bien la materia, deja muchos ejemplos, las clases son un poco pesadas, califica muy estricto en los exámenes, pero ha mejorado mucho respecto a otros años'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2019-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'e4a13b6917f0e8489792a7028c5a5869ab98c29a77ab6f3922a3335071b8c351'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Siempre deja quices, da la clase muy claro. Sin embargo, a la hora del examen cambia mucho la forma de ser, se comporta seria y cortante.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '4c135c03b3825283bb62ba07b11698abf734878f289c3f2f4996d5a3c83b7d4f'::TEXT, ARRAY[3131]::BIGINT[]),
    (446::BIGINT, 'Muy buena profesora. Las evalaciones sí tienen sentido (no como otros). Me gustó el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '9cbfe78ab736b2e06f3367899363121e60be42524f84cb5ddccb38c768f1b7a8'::TEXT, ARRAY[963, 1728, 1743, 1742]::BIGINT[]),
    (446::BIGINT, 'El curso en si es fácil, nada más es estar al día con la materia y participar en clase.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '5d90ac48950d66ba6cd7f935e5cb4970cbb0b6bd99b75408d5bf25341d36b02a'::TEXT, ARRAY[1742]::BIGINT[]),
    (446::BIGINT, 'El curso es llevadero, solamente es no quedarse con lo que da en clase y buscar practica. Atiende muy bien cualquier duda .'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'd193cbc9fa3ada39dac2ca23faa47507933544fa1bf2b5502ab38658a1e9f62a'::TEXT, ARRAY[1742]::BIGINT[]),
    (446::BIGINT, 'Me pareció buena profe , da lo necesario para entender, responde muy amable todo tipo de dudas y como ella dice hay que buscar más ejercicios para practicar, el curso es pasable.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'e9dd94d9699fd5bc90cf569fa076caa2a3064a50faed6940884a79dcec0ec3d3'::TEXT, ARRAY[1742]::BIGINT[]),
    (446::BIGINT, 'En realidad ah mejorado mucho, ya no califica bueno o malo, es clase entretenida! Además, es buena persona.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2017-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'f3b6f027c3400652fe9c2f641145c6e7cc011731984526e214bc3d0203a50046'::TEXT, ARRAY[963]::BIGINT[]),
    (446::BIGINT, 'Es super buena persona y muy humilde, en consulta es excelente, explica muy bien pero los examenes sin son duros pero hay trabajos colaborativos que ayudan mucho al igual que si usted hace una presentacion puede ganar puntos extras y también valora mucho el esfuerzo del estudiante. excelente profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-08-09T00:00:00+00:00'::TIMESTAMPTZ, '575d4fa028f0ec293672070486a601d239f52b9410d0bff7d4c8d5fa5c62b1e7'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Como persona es buena gente, pero como profesora da mucho que desear, califica Bueno o malo, los examenes son largos y solo acepta dudas en 20 min. no tiene flexibilidad con la consulta, las presentaciones no sirven de mucho Irresponsable No meteria nada mas con ella'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-18T00:00:00+00:00'::TIMESTAMPTZ, '34389dc45db73186e024a3b1a699eda62e9e66d23b8eb08a15a95e1e7bc1aeac'::TEXT, ARRAY[963, 1728, 1743, 1742]::BIGINT[]),
    (446::BIGINT, 'No da instrucciones claras, es desordenada y califica o bueno o malo, no ve procedimiento. Es buena gente pero pedagogicamente le falta.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, '60a81c88fdf1e3c34736b26107e89c7f17404c635cc8d2d6c9ae310e2c5f1ddf'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Este semestre fue mi mejor curso. Excelente! Busca que uno participe mucho en clase y se preocupa por la asistencia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'ea99a86113d4908eee41c875e21ed66480603036ff6e627ccf7eac98ee885476'::TEXT, ARRAY[1719]::BIGINT[]),
    (446::BIGINT, 'En los trabajos hay que adivinar aveces que es lo que quiere, aunque ni lo haya dicho (ni ella sabe lo que quiere)...Redacta muy mal las instrucciones de las trabajos y exámenes. Por lo menos es buena persona.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '7e1fbafe7250632a66c263f7165a85742f6281d09e054d5a5174af4285045a5a'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'edd380b10246ff9da35d57b7f3ffbb97e807b00dbc1d7218da3f19016ba76b52'::TEXT, ARRAY[1719]::BIGINT[]),
    (446::BIGINT, 'Pésima no sabe de lo que habla, califica solo los resultados y nada de procedimientos, no le ayuda ni en 0.1 que le falte, eso no es nada, sino que es super desordenada, cerrada más que un huevo, no se puede contradecir y es una falsa, Para nada la recomiendo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2016-06-10T00:00:00+00:00'::TIMESTAMPTZ, '3d1da85276b96ab9f630e82c9348144504071a3ae5b0c805edbcd3dd70aa6eaa'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Es medio vaga, pero si pone atencion en clase y va a consulta pasa sin problemas'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ae6b65e8ab133eeebc7ed31c993888860b0d893370ade4148107a9214d5dc06f'::TEXT, ARRAY[1719]::BIGINT[]),
    (446::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-07T00:00:00+00:00'::TIMESTAMPTZ, '0a5d57fda1bf94daaa6f2d5bd3faa5acdf6b9036d011add564c41cad8ddde692'::TEXT, ARRAY[1719]::BIGINT[]),
    (446::BIGINT, 'Pésima profesora,definitivamente no sabe enseñar, es vaga, falta mucho a clases y no sabe ni lo que esta calificando, muy desordenada para dar las clases....'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '572bdf98b5c0b8fb2a17df948368641bb6a28239b24cf5c48a8cff5b1954ab35'::TEXT, ARRAY[1719]::BIGINT[]),
    (446::BIGINT, 'Falta de profesionalidad, espero no toparme con ella de nuevo.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-28T00:00:00+00:00'::TIMESTAMPTZ, '31d7f734fb3f49e13556976d0a06dc39f97f4d7f1c84f44278aa4912dfecc59f'::TEXT, ARRAY[1722, 1719, 1723, 1720]::BIGINT[]),
    (446::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'eb7daaa9b58cf8aedcb2fa0f5231f17e0c157def91323352f6acd899fe5ba87a'::TEXT, ARRAY[1722, 1719, 1723, 1720]::BIGINT[]),
    (446::BIGINT, 'Es mucho más fácil que fernando y se salen con las bases justas para costos 2, es un poco vaga pero si usted se involucra en el proyecto con tiempo le ayuda mucho'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '2265015ef6b1f1b6c1341f6b33765bffbb760a779be3d0afa5a0ff6ebd612cfd'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Excelente persona, muy amable y ayuda mucho a los estudiantes. Sin embargo, en clases se pierde mucho y a veces no se le entiende la materia. Los proyectos son muy fáciles, no es muy exigente con los mismos y los exámenes son fáciles de pasar. La nota de quices y tareas es casi un regalo'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '69411ba536b45761547f2828511be315ab4ed41fd300aa26c65d70ba0310b2bf'::TEXT, ARRAY[1728]::BIGINT[]),
    (446::BIGINT, 'Muy amable, y es facil pasar porque los examenes no son dificiles y deja muchos trabajos grupales. LO malo es que no planifica bien las lecciones ya que no se le entiende mucho y si matricula en la mañana las clases se van rápido porque llega tarde y luego tiene que ir a desayunar.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '56dffd102c9b68f8382b9bcdb64f5d994e70c82919930edbdf0562247fe157c4'::TEXT, ARRAY[1728]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
